// Primer cards for Clustering (spec/PRIMERS.md). Sources: course summary (Raz Katz) pp. 107–115 and HW6 only (no clustering slides available).
(function () {
  const R = String.raw;
  window.PRIMERS = window.PRIMERS || {};
  window.PRIMERS.clustering = [

    // ───────────────────────── 1 · summary p. 107 + HW6 ─────────────────────────
    { title: "Clustering: no labels",
      what: R`<p>Until now every sample came with a label, and the labels steered the learning. In <b>unsupervised learning</b> you only get the samples, and still look for structure.</p>
<p><b>Clustering</b> splits the samples into groups (clusters): samples in the same cluster should be more similar to each other than to samples in other clusters.</p>
<div class="fig"><svg viewBox="0 0 480 180" width="480" role="img" aria-label="Left: grey points with no labels. Right: the same points coloured into three groups, each group tight, the groups far apart"><defs><marker id="clp-a1" viewBox="0 0 10 10" refX="9" refY="5" markerWidth="7" markerHeight="7" orient="auto-start-reverse"><path d="M0,0 L10,5 L0,10 z" style="fill:var(--muted)"/></marker></defs><circle cx="88.3" cy="60.7" r="5.5" style="fill:var(--muted)"/><circle cx="66.3" cy="30.8" r="5.5" style="fill:var(--muted)"/><circle cx="61.4" cy="50.4" r="5.5" style="fill:var(--muted)"/><circle cx="47.9" cy="66.5" r="5.5" style="fill:var(--muted)"/><circle cx="76.5" cy="77.2" r="5.5" style="fill:var(--muted)"/><circle cx="77.8" cy="40.7" r="5.5" style="fill:var(--muted)"/><circle cx="144.6" cy="47.3" r="5.5" style="fill:var(--muted)"/><circle cx="179.3" cy="53.1" r="5.5" style="fill:var(--muted)"/><circle cx="169.7" cy="75.7" r="5.5" style="fill:var(--muted)"/><circle cx="149.6" cy="18.6" r="5.5" style="fill:var(--muted)"/><circle cx="130.8" cy="46.5" r="5.5" style="fill:var(--muted)"/><circle cx="179.3" cy="35.5" r="5.5" style="fill:var(--muted)"/><circle cx="121" cy="98.8" r="5.5" style="fill:var(--muted)"/><circle cx="102.2" cy="98.1" r="5.5" style="fill:var(--muted)"/><circle cx="123.6" cy="140.3" r="5.5" style="fill:var(--muted)"/><circle cx="107.4" cy="146.1" r="5.5" style="fill:var(--muted)"/><circle cx="101.2" cy="125" r="5.5" style="fill:var(--muted)"/><circle cx="112" cy="109.2" r="5.5" style="fill:var(--muted)"/><circle cx="358.3" cy="60.7" r="5.5" style="fill:var(--accent)"/><circle cx="336.3" cy="30.8" r="5.5" style="fill:var(--accent)"/><circle cx="331.4" cy="50.4" r="5.5" style="fill:var(--accent)"/><circle cx="317.9" cy="66.5" r="5.5" style="fill:var(--accent)"/><circle cx="346.5" cy="77.2" r="5.5" style="fill:var(--accent)"/><circle cx="347.8" cy="40.7" r="5.5" style="fill:var(--accent)"/><circle cx="414.6" cy="47.3" r="5.5" style="fill:var(--got)"/><circle cx="449.3" cy="53.1" r="5.5" style="fill:var(--got)"/><circle cx="439.7" cy="75.7" r="5.5" style="fill:var(--got)"/><circle cx="419.6" cy="18.6" r="5.5" style="fill:var(--got)"/><circle cx="400.8" cy="46.5" r="5.5" style="fill:var(--got)"/><circle cx="449.3" cy="35.5" r="5.5" style="fill:var(--got)"/><circle cx="391" cy="98.8" r="5.5" style="fill:var(--shaky)"/><circle cx="372.2" cy="98.1" r="5.5" style="fill:var(--shaky)"/><circle cx="393.6" cy="140.3" r="5.5" style="fill:var(--shaky)"/><circle cx="377.4" cy="146.1" r="5.5" style="fill:var(--shaky)"/><circle cx="371.2" cy="125" r="5.5" style="fill:var(--shaky)"/><circle cx="382" cy="109.2" r="5.5" style="fill:var(--shaky)"/><line x1="222" y1="90" x2="262" y2="90" style="stroke:var(--muted)" stroke-width="2" marker-end="url(#clp-a1)"/><text x="110" y="172" text-anchor="middle" font-size="12" style="fill:var(--muted)">samples, no labels</text><text x="380" y="172" text-anchor="middle" font-size="12" style="fill:var(--accent-ink)" font-weight="700">k = 3 clusters</text></svg></div>
<p><b>Why there's no single right answer:</b> nobody tells you what "similar" means. You choose it: a distance measure, and an algorithm. Change either one and the clusters can change.</p>`,
      formula: R`\[D = \{x_1, \dots, x_m\}\ \longrightarrow\ C_1, \dots, C_k\]<p>The clusters don't overlap, and together they hold every sample.</p>`,
      example: { src: "HW6 Part 1 (K-means for image compression)", html: R`<p>An image of 768 × 1366 pixels. Each pixel is one sample with 3 features (R, G, B), so \(X\) has 1,049,088 rows and 3 columns. No labels.</p>
<p>Cluster the pixels by color with K-means, k = 16, then replace every pixel by its cluster's centroid color. The image now uses only 16 colors: it's <b>compressed</b>. It still looks like the original, because only similar colors got merged.</p>` },
      mistakes: R`<ul><li>No labels → no accuracy to check. How good a clustering is needs its own score (\(S_C\), silhouette: later cards).</li><li>k, the number of clusters, isn't in the data: you choose it.</li></ul>`,
      where: [] },

    // ───────────────────────── 2 · summary pp. 107–109 + HW6 ─────────────────────────
    { title: "Distances: similar = close",
      what: R`<p>Similar = close: we need a distance \(d(x, y)\), small = similar.</p>
<p>A real distance is ≥ 0 with 3 rules: \(d(x, y) = 0\) exactly when \(x = y\); \(d(x, y) = d(y, x)\); a detour is never shorter: \(d(x, y) \le d(x, z) + d(z, y)\).</p>
<div class="fig"><svg viewBox="0 0 440 200" width="440" role="img" aria-label="Two points 4 apart across and 3 apart up: the straight line has length 5 (L2), walking along the grid takes 7 (L1), the biggest single difference is 4 (L-infinity)"><line x1="50" y1="40" x2="50" y2="178" style="stroke:var(--muted)" stroke-width="0.6" stroke-dasharray="2 4"/><line x1="90" y1="40" x2="90" y2="178" style="stroke:var(--muted)" stroke-width="0.6" stroke-dasharray="2 4"/><line x1="130" y1="40" x2="130" y2="178" style="stroke:var(--muted)" stroke-width="0.6" stroke-dasharray="2 4"/><line x1="170" y1="40" x2="170" y2="178" style="stroke:var(--muted)" stroke-width="0.6" stroke-dasharray="2 4"/><line x1="210" y1="40" x2="210" y2="178" style="stroke:var(--muted)" stroke-width="0.6" stroke-dasharray="2 4"/><line x1="42" y1="170" x2="220" y2="170" style="stroke:var(--muted)" stroke-width="0.6" stroke-dasharray="2 4"/><line x1="42" y1="130" x2="220" y2="130" style="stroke:var(--muted)" stroke-width="0.6" stroke-dasharray="2 4"/><line x1="42" y1="90" x2="220" y2="90" style="stroke:var(--muted)" stroke-width="0.6" stroke-dasharray="2 4"/><line x1="42" y1="50" x2="220" y2="50" style="stroke:var(--muted)" stroke-width="0.6" stroke-dasharray="2 4"/><line x1="50" y1="170" x2="210" y2="170" style="stroke:var(--got)" stroke-width="5"/><line x1="50" y1="170" x2="210" y2="170" style="stroke:var(--shaky)" stroke-width="2" stroke-dasharray="6 4"/><line x1="210" y1="170" x2="210" y2="50" style="stroke:var(--shaky)" stroke-width="2" stroke-dasharray="6 4"/><line x1="50" y1="170" x2="210" y2="50" style="stroke:var(--accent)" stroke-width="2.5"/><circle cx="50" cy="170" r="6" style="fill:var(--accent-ink)"/><circle cx="210" cy="50" r="6" style="fill:var(--accent-ink)"/><text x="40" y="174" text-anchor="end" font-size="13" fill="currentColor" font-weight="700">x</text><text x="200" y="54" text-anchor="end" font-size="13" fill="currentColor" font-weight="700">y</text><text x="130" y="190" text-anchor="middle" font-size="12" style="fill:var(--muted)">4</text><text x="222" y="114" text-anchor="start" font-size="12" style="fill:var(--muted)">3</text><text x="262" y="70" text-anchor="start" font-size="12" style="fill:var(--accent-ink)" font-weight="700">L2 = √(4² + 3²) = 5</text><text x="262" y="88" text-anchor="start" font-size="11" style="fill:var(--muted)">the straight line</text><text x="262" y="118" text-anchor="start" font-size="12" style="fill:var(--shaky)" font-weight="700">L1 = 4 + 3 = 7</text><text x="262" y="136" text-anchor="start" font-size="11" style="fill:var(--muted)">walk along the grid</text><text x="262" y="166" text-anchor="start" font-size="12" style="fill:var(--got)" font-weight="700">L∞ = max(4, 3) = 4</text><text x="262" y="184" text-anchor="start" font-size="11" style="fill:var(--muted)">the biggest single gap</text></svg></div>
<p><b>The \(L_p\) family</b> adds up the gaps feature by feature: \(p = 1\) walks the grid, \(p = 2\) is the straight line, \(p \to \infty\) keeps only the biggest gap.</p>
<p><b>Scaling matters</b> (like in KNN): a feature in big numbers makes big gaps and drowns the others.</p>`,
      formula: R`\[\begin{aligned}d_p(x, y) &= \|x - y\|_p\\ &= \Big(\sum_i |x_i - y_i|^p\Big)^{1/p}\end{aligned}\]<p>\(i\) runs over the features, \(p \ge 1\). The sheet has \(p = 1, 2, \infty\) only: [sheet: Normed distance] · [sheet: L1 norm] · [sheet: L2 norm]</p>`,
      remember: R`\[\mathrm{Cos}\big(\theta(x, y)\big) = \frac{x^\top y}{\|x\|\,\|y\|},\qquad d_{cos} = 1 - \mathrm{Cos}\]<p>Cosine: only the angle between \(x\) and \(y\) counts, not their length. Not on the sheet.</p>`,
      example: { src: "HW6 Q2 (l_p_dist_from_centroids)", html: R`<p>HW6 computes the \(L_p\) distance from every pixel to every centroid at once:</p>
<pre><code>absolute_differences = np.abs(
    X[np.newaxis, :, :] - centroids[:, np.newaxis, :])
distances = np.sum(absolute_differences ** p,
                   axis=2) ** (1 / p)</code></pre>
<p>Line 1: every pixel minus every centroid, per feature, absolute value. Line 2: to the power p, add up over the features (axis 2), then the 1/p root. That's the formula above.</p>
<div class="sizecheck"><span class="tag sizetag">Size check</span><p><code>X[np.newaxis]</code>: (1, n, 3) · <code>centroids[:, np.newaxis]</code>: (k, 1, 3) → the difference is (k, n, 3): every centroid against every pixel ✓</p><p>Sum over axis 2 (the 3 colors) → <code>distances</code>: (k, n). Entry [j, i] = pixel i to centroid j ✓</p></div>` },
      try: { src: "Course summary, p. 108",
        q: R`<p>The summary writes \(d_{L_\infty}(x, y) = \max_i |x_i - y_i| = \lim_{p\to\infty} d_{L_p}(x, y)\). Why does a big p keep only the biggest gap? Use the gaps 4 and 3 from the figure.</p>`,
        a: R`<p>The power p blows up the biggest gap much more than the others: \(4^{10} = 1{,}048{,}576\) but \(3^{10} = 59{,}049\). So the sum is ≈ (biggest gap)\(^p\), and the \(1/p\) root gives back ≈ the biggest gap.</p>
<p>Numbers: \(p = 1\) → 7, \(p = 2\) → 5, \(p = 10\) → 4.02, \(p = 50\) → 4.00000005.</p>` },
      mistakes: R`<ul><li>\(L_1\) = sum of |gaps|: no squares, no root.</li><li>Not scaling: a feature in the thousands drowns a feature between 0 and 1.</li></ul>`,
      where: ["2025-A Q2.4", "2025-A Q2.5", "2026-A Q4.4"] },

    // ───────────────────────── 3 · summary pp. 108–109 ─────────────────────────
    { title: "Naive cluster growing",
      what: R`<p>The simplest algorithm. Pick a threshold \(d_0\). Take any sample that has no cluster yet: it starts a new cluster. Keep adding every unclustered sample within \(d_0\) of the cluster, until nothing more is in reach. Then start the next cluster.</p>
<div class="fig"><svg viewBox="0 0 480 182" width="480" role="img" aria-label="The same points twice. Left, a small threshold links only very close points: two tight groups and one loner. Right, a big threshold links everything into one cluster"><line x1="74.2" y1="56.9" x2="54.9" y2="56.5" style="stroke:var(--muted)" stroke-width="1.2"/><line x1="74.2" y1="56.9" x2="63.1" y2="77.3" style="stroke:var(--muted)" stroke-width="1.2"/><line x1="49.7" y1="30.8" x2="54.9" y2="56.5" style="stroke:var(--muted)" stroke-width="1.2"/><line x1="49.7" y1="30.8" x2="40.6" y2="47.7" style="stroke:var(--muted)" stroke-width="1.2"/><line x1="54.9" y1="56.5" x2="40.6" y2="47.7" style="stroke:var(--muted)" stroke-width="1.2"/><line x1="54.9" y1="56.5" x2="63.1" y2="77.3" style="stroke:var(--muted)" stroke-width="1.2"/><line x1="54.9" y1="56.5" x2="38" y2="74.3" style="stroke:var(--muted)" stroke-width="1.2"/><line x1="40.6" y1="47.7" x2="38" y2="74.3" style="stroke:var(--muted)" stroke-width="1.2"/><line x1="63.1" y1="77.3" x2="38" y2="74.3" style="stroke:var(--muted)" stroke-width="1.2"/><line x1="157.4" y1="51.4" x2="158.1" y2="66" style="stroke:var(--muted)" stroke-width="1.2"/><line x1="157.4" y1="51.4" x2="171.7" y2="53.3" style="stroke:var(--muted)" stroke-width="1.2"/><line x1="157.4" y1="51.4" x2="141.5" y2="52" style="stroke:var(--muted)" stroke-width="1.2"/><line x1="157.4" y1="51.4" x2="172" y2="70.9" style="stroke:var(--muted)" stroke-width="1.2"/><line x1="158.1" y1="66" x2="171.7" y2="53.3" style="stroke:var(--muted)" stroke-width="1.2"/><line x1="158.1" y1="66" x2="141.5" y2="52" style="stroke:var(--muted)" stroke-width="1.2"/><line x1="158.1" y1="66" x2="172" y2="70.9" style="stroke:var(--muted)" stroke-width="1.2"/><line x1="158.1" y1="66" x2="142.6" y2="79.4" style="stroke:var(--muted)" stroke-width="1.2"/><line x1="171.7" y1="53.3" x2="172" y2="70.9" style="stroke:var(--muted)" stroke-width="1.2"/><line x1="141.5" y1="52" x2="142.6" y2="79.4" style="stroke:var(--muted)" stroke-width="1.2"/><circle cx="74.2" cy="56.9" r="5.5" style="fill:var(--accent)"/><circle cx="49.7" cy="30.8" r="5.5" style="fill:var(--accent)"/><circle cx="54.9" cy="56.5" r="5.5" style="fill:var(--accent)"/><circle cx="40.6" cy="47.7" r="5.5" style="fill:var(--accent)"/><circle cx="63.1" cy="77.3" r="5.5" style="fill:var(--accent)"/><circle cx="38" cy="74.3" r="5.5" style="fill:var(--accent)"/><circle cx="157.4" cy="51.4" r="5.5" style="fill:var(--got)"/><circle cx="158.1" cy="66" r="5.5" style="fill:var(--got)"/><circle cx="171.7" cy="53.3" r="5.5" style="fill:var(--got)"/><circle cx="141.5" cy="52" r="5.5" style="fill:var(--got)"/><circle cx="172" cy="70.9" r="5.5" style="fill:var(--got)"/><circle cx="142.6" cy="79.4" r="5.5" style="fill:var(--got)"/><circle cx="110" cy="135" r="5.5" style="fill:var(--shaky)"/><text x="110" y="172" text-anchor="middle" font-size="12" style="fill:var(--accent-ink)" font-weight="700">small d₀: 3 clusters</text><line x1="339.2" y1="56.9" x2="314.7" y2="30.8" style="stroke:var(--muted)" stroke-width="1.2"/><line x1="339.2" y1="56.9" x2="319.9" y2="56.5" style="stroke:var(--muted)" stroke-width="1.2"/><line x1="339.2" y1="56.9" x2="305.6" y2="47.7" style="stroke:var(--muted)" stroke-width="1.2"/><line x1="339.2" y1="56.9" x2="328.1" y2="77.3" style="stroke:var(--muted)" stroke-width="1.2"/><line x1="339.2" y1="56.9" x2="303" y2="74.3" style="stroke:var(--muted)" stroke-width="1.2"/><line x1="339.2" y1="56.9" x2="406.5" y2="52" style="stroke:var(--muted)" stroke-width="1.2"/><line x1="339.2" y1="56.9" x2="407.6" y2="79.4" style="stroke:var(--muted)" stroke-width="1.2"/><line x1="314.7" y1="30.8" x2="319.9" y2="56.5" style="stroke:var(--muted)" stroke-width="1.2"/><line x1="314.7" y1="30.8" x2="305.6" y2="47.7" style="stroke:var(--muted)" stroke-width="1.2"/><line x1="314.7" y1="30.8" x2="328.1" y2="77.3" style="stroke:var(--muted)" stroke-width="1.2"/><line x1="314.7" y1="30.8" x2="303" y2="74.3" style="stroke:var(--muted)" stroke-width="1.2"/><line x1="319.9" y1="56.5" x2="305.6" y2="47.7" style="stroke:var(--muted)" stroke-width="1.2"/><line x1="319.9" y1="56.5" x2="328.1" y2="77.3" style="stroke:var(--muted)" stroke-width="1.2"/><line x1="319.9" y1="56.5" x2="303" y2="74.3" style="stroke:var(--muted)" stroke-width="1.2"/><line x1="305.6" y1="47.7" x2="328.1" y2="77.3" style="stroke:var(--muted)" stroke-width="1.2"/><line x1="305.6" y1="47.7" x2="303" y2="74.3" style="stroke:var(--muted)" stroke-width="1.2"/><line x1="328.1" y1="77.3" x2="303" y2="74.3" style="stroke:var(--muted)" stroke-width="1.2"/><line x1="328.1" y1="77.3" x2="375" y2="135" style="stroke:var(--muted)" stroke-width="1.2"/><line x1="422.4" y1="51.4" x2="423.1" y2="66" style="stroke:var(--muted)" stroke-width="1.2"/><line x1="422.4" y1="51.4" x2="436.7" y2="53.3" style="stroke:var(--muted)" stroke-width="1.2"/><line x1="422.4" y1="51.4" x2="406.5" y2="52" style="stroke:var(--muted)" stroke-width="1.2"/><line x1="422.4" y1="51.4" x2="437" y2="70.9" style="stroke:var(--muted)" stroke-width="1.2"/><line x1="422.4" y1="51.4" x2="407.6" y2="79.4" style="stroke:var(--muted)" stroke-width="1.2"/><line x1="423.1" y1="66" x2="436.7" y2="53.3" style="stroke:var(--muted)" stroke-width="1.2"/><line x1="423.1" y1="66" x2="406.5" y2="52" style="stroke:var(--muted)" stroke-width="1.2"/><line x1="423.1" y1="66" x2="437" y2="70.9" style="stroke:var(--muted)" stroke-width="1.2"/><line x1="423.1" y1="66" x2="407.6" y2="79.4" style="stroke:var(--muted)" stroke-width="1.2"/><line x1="436.7" y1="53.3" x2="406.5" y2="52" style="stroke:var(--muted)" stroke-width="1.2"/><line x1="436.7" y1="53.3" x2="437" y2="70.9" style="stroke:var(--muted)" stroke-width="1.2"/><line x1="436.7" y1="53.3" x2="407.6" y2="79.4" style="stroke:var(--muted)" stroke-width="1.2"/><line x1="406.5" y1="52" x2="437" y2="70.9" style="stroke:var(--muted)" stroke-width="1.2"/><line x1="406.5" y1="52" x2="407.6" y2="79.4" style="stroke:var(--muted)" stroke-width="1.2"/><line x1="437" y1="70.9" x2="407.6" y2="79.4" style="stroke:var(--muted)" stroke-width="1.2"/><line x1="407.6" y1="79.4" x2="375" y2="135" style="stroke:var(--muted)" stroke-width="1.2"/><circle cx="339.2" cy="56.9" r="5.5" style="fill:var(--accent)"/><circle cx="314.7" cy="30.8" r="5.5" style="fill:var(--accent)"/><circle cx="319.9" cy="56.5" r="5.5" style="fill:var(--accent)"/><circle cx="305.6" cy="47.7" r="5.5" style="fill:var(--accent)"/><circle cx="328.1" cy="77.3" r="5.5" style="fill:var(--accent)"/><circle cx="303" cy="74.3" r="5.5" style="fill:var(--accent)"/><circle cx="422.4" cy="51.4" r="5.5" style="fill:var(--accent)"/><circle cx="423.1" cy="66" r="5.5" style="fill:var(--accent)"/><circle cx="436.7" cy="53.3" r="5.5" style="fill:var(--accent)"/><circle cx="406.5" cy="52" r="5.5" style="fill:var(--accent)"/><circle cx="437" cy="70.9" r="5.5" style="fill:var(--accent)"/><circle cx="407.6" cy="79.4" r="5.5" style="fill:var(--accent)"/><circle cx="375" cy="135" r="5.5" style="fill:var(--accent)"/><text x="375" y="172" text-anchor="middle" font-size="12" style="fill:var(--accent-ink)" font-weight="700">big d₀: 1 cluster</text><line x1="238" y1="20" x2="238" y2="160" style="stroke:var(--muted)" stroke-width="1" stroke-dasharray="3 4"/></svg></div>
<p><b>Picture:</b> link every two samples closer than \(d_0\); each linked-up group is one cluster.</p>
<p><b>Why it's weak:</b> the result hangs on \(d_0\), which you must guess in advance. It checks all pairs: \(O(n^2)\). And no number says how good the result is, so there's nothing to optimize. Next card: such a number.</p>`,
      formula: R`\[\text{add } e \text{ to } C_s\ \text{ while }\ d(e, C_s) \le d_0\]`,
      example: { src: "Course summary, p. 108 ('Different d0 may lead to different results')", html: R`<p>The same 2D data, three thresholds:</p>
<ul><li>\(d_0 = 0.3\): links everywhere, one big tangle.</li><li>\(d_0 = 0.1\): a few clear groups.</li><li>\(d_0 = 0.03\): almost no links, most samples alone.</li></ul>
<p>Too big → one cluster. Too small → every sample alone.</p>` },
      mistakes: R`<ul><li>\(d_0\) is a hyper-parameter you set; the algorithm doesn't learn it.</li></ul>`,
      where: [] },

    // ───────────────────────── 4 · summary pp. 109–110 + HW6 ─────────────────────────
    { title: "Within-cluster scatter (WCSS)",
      what: R`<p>To optimize we need one number per clustering. Good clusters are <b>tight</b>, and far from each other. Start with tight.</p>
<p>Give each cluster a center, its <b>centroid</b> \(\mu_i\) = the mean of its samples. Then \(S_C\) = every sample's squared distance to its own centroid, all added up.</p>
<div class="fig"><svg viewBox="0 0 420 138" width="420" role="img" aria-label="Two clusters; every sample has a dashed spoke to its own cluster center, marked with a cross. S_C adds up the squared lengths of all the spokes"><line x1="120.6" y1="34.6" x2="121.5" y2="54" style="stroke:var(--accent)" stroke-width="1.3" stroke-dasharray="4 3"/><line x1="168.3" y1="36.5" x2="121.5" y2="54" style="stroke:var(--accent)" stroke-width="1.3" stroke-dasharray="4 3"/><line x1="112.6" y1="80.5" x2="121.5" y2="54" style="stroke:var(--accent)" stroke-width="1.3" stroke-dasharray="4 3"/><line x1="88.2" y1="28.4" x2="121.5" y2="54" style="stroke:var(--accent)" stroke-width="1.3" stroke-dasharray="4 3"/><line x1="101.4" y1="57" x2="121.5" y2="54" style="stroke:var(--accent)" stroke-width="1.3" stroke-dasharray="4 3"/><line x1="137.6" y1="87.1" x2="121.5" y2="54" style="stroke:var(--accent)" stroke-width="1.3" stroke-dasharray="4 3"/><circle cx="120.6" cy="34.6" r="5.5" style="fill:var(--accent)"/><circle cx="168.3" cy="36.5" r="5.5" style="fill:var(--accent)"/><circle cx="112.6" cy="80.5" r="5.5" style="fill:var(--accent)"/><circle cx="88.2" cy="28.4" r="5.5" style="fill:var(--accent)"/><circle cx="101.4" cy="57" r="5.5" style="fill:var(--accent)"/><circle cx="137.6" cy="87.1" r="5.5" style="fill:var(--accent)"/><path d="M114.5,47 L128.5,61 M114.5,61 L128.5,47" style="stroke:var(--panel)" stroke-width="7" stroke-linecap="round"/><path d="M114.5,47 L128.5,61 M114.5,61 L128.5,47" style="stroke:var(--accent-ink)" stroke-width="3.2" stroke-linecap="round"/><text x="121.5" y="126.8" text-anchor="middle" font-size="12" style="fill:var(--accent-ink)" font-weight="700">centroid μ₁</text><line x1="263.7" y1="58" x2="294.6" y2="57.5" style="stroke:var(--got)" stroke-width="1.3" stroke-dasharray="4 3"/><line x1="276.5" y1="22" x2="294.6" y2="57.5" style="stroke:var(--got)" stroke-width="1.3" stroke-dasharray="4 3"/><line x1="323.9" y1="59.7" x2="294.6" y2="57.5" style="stroke:var(--got)" stroke-width="1.3" stroke-dasharray="4 3"/><line x1="301.4" y1="33.8" x2="294.6" y2="57.5" style="stroke:var(--got)" stroke-width="1.3" stroke-dasharray="4 3"/><line x1="304.7" y1="74.6" x2="294.6" y2="57.5" style="stroke:var(--got)" stroke-width="1.3" stroke-dasharray="4 3"/><line x1="297.4" y1="96.8" x2="294.6" y2="57.5" style="stroke:var(--got)" stroke-width="1.3" stroke-dasharray="4 3"/><circle cx="263.7" cy="58" r="5.5" style="fill:var(--got)"/><circle cx="276.5" cy="22" r="5.5" style="fill:var(--got)"/><circle cx="323.9" cy="59.7" r="5.5" style="fill:var(--got)"/><circle cx="301.4" cy="33.8" r="5.5" style="fill:var(--got)"/><circle cx="304.7" cy="74.6" r="5.5" style="fill:var(--got)"/><circle cx="297.4" cy="96.8" r="5.5" style="fill:var(--got)"/><path d="M287.6,50.5 L301.6,64.5 M287.6,64.5 L301.6,50.5" style="stroke:var(--panel)" stroke-width="7" stroke-linecap="round"/><path d="M287.6,50.5 L301.6,64.5 M287.6,64.5 L301.6,50.5" style="stroke:var(--accent-ink)" stroke-width="3.2" stroke-linecap="round"/><text x="294.6" y="126.8" text-anchor="middle" font-size="12" style="fill:var(--accent-ink)" font-weight="700">centroid μ₂</text></svg></div>
<p><b>Picture:</b> a spoke from each sample to its centroid. \(S_C\) = the sum of the squared spoke lengths. Small = tight.</p>
<p><b>Why not just try every split?</b> m samples into k clusters: about \(k^m/k!\) ways. Far too many. So we search smartly: K-means.</p>`,
      formula: R`\[\begin{aligned}S_C &= \sum_{i=1}^k\ \sum_{x \in C_i}\|x - \mu_i\|^2\\ \mu_i &= \frac1{n_i}\sum_{x\in C_i} x,\qquad n_i = |C_i|\end{aligned}\]<p>[sheet: Within-cluster sum of squares (WCSS)]: the same thing, called WCSS.</p>`,
      example: { src: "HW6 Q3 (the final WCSS)", html: R`<p>HW6 gets the WCSS in one line from the distance table (entry [j, i] = pixel i to centroid j):</p>
<pre><code>WCSS = np.sum(np.min(distances, axis=0) ** p)</code></pre>
<p><code>np.min(…, axis=0)</code>: for each pixel, the distance to its nearest centroid, which is its own (every pixel was assigned to the nearest one). To the power p = 2: the squared spoke. Sum over the pixels: \(S_C\).</p>
<div class="sizecheck"><span class="tag sizetag">Size check</span><p><code>distances</code>: (k, n) → min over axis 0 (the centroids) → (n,): one number per pixel → sum → one number ✓</p></div>` },
      mistakes: R`<ul><li>\(\|x - \mu_i\|^2\) = sum of squared gaps, <b>no root</b>.</li><li>Each sample counts once, to its <b>own</b> centroid.</li></ul>`,
      where: ["2025-A Q2.2", "2025-C Q5.1", "2025-C Q5.4", "2026-A Q4.1"] },

    // ───────────────────────── 5 · summary pp. 110–111 + HW6 ─────────────────────────
    { title: "Total = within + between",
      what: R`<p>The other goal: clusters far apart. Let \(\mu\) = the mean of <b>all</b> the data. \(S_B\) = each centroid's squared distance to \(\mu\), counted once per sample in its cluster. \(S_T\) = every sample's squared distance to \(\mu\): the spread of the whole data, no clusters involved.</p>
<div class="fig"><svg viewBox="0 0 420 170" width="420" role="img" aria-label="Two clusters. Thin dashed spokes join each sample to its own center (within-cluster scatter). Thick lines join each cluster center to the mean of all the data (between-cluster scatter)"><line x1="91.5" y1="77.5" x2="78.5" y2="80" style="stroke:var(--accent)" stroke-width="1.2" stroke-dasharray="4 3"/><line x1="58.8" y1="37.8" x2="78.5" y2="80" style="stroke:var(--accent)" stroke-width="1.2" stroke-dasharray="4 3"/><line x1="53.3" y1="98.6" x2="78.5" y2="80" style="stroke:var(--accent)" stroke-width="1.2" stroke-dasharray="4 3"/><line x1="117.6" y1="95.3" x2="78.5" y2="80" style="stroke:var(--accent)" stroke-width="1.2" stroke-dasharray="4 3"/><line x1="71.1" y1="90.7" x2="78.5" y2="80" style="stroke:var(--accent)" stroke-width="1.2" stroke-dasharray="4 3"/><line x1="302" y1="59.4" x2="311.7" y2="66.7" style="stroke:var(--got)" stroke-width="1.2" stroke-dasharray="4 3"/><line x1="333.8" y1="66.3" x2="311.7" y2="66.7" style="stroke:var(--got)" stroke-width="1.2" stroke-dasharray="4 3"/><line x1="317.2" y1="76.8" x2="311.7" y2="66.7" style="stroke:var(--got)" stroke-width="1.2" stroke-dasharray="4 3"/><line x1="347.2" y1="86.1" x2="311.7" y2="66.7" style="stroke:var(--got)" stroke-width="1.2" stroke-dasharray="4 3"/><line x1="269.8" y1="88.2" x2="311.7" y2="66.7" style="stroke:var(--got)" stroke-width="1.2" stroke-dasharray="4 3"/><line x1="290.1" y1="41.5" x2="311.7" y2="66.7" style="stroke:var(--got)" stroke-width="1.2" stroke-dasharray="4 3"/><line x1="322" y1="48.4" x2="311.7" y2="66.7" style="stroke:var(--got)" stroke-width="1.2" stroke-dasharray="4 3"/><line x1="78.5" y1="80" x2="214.5" y2="72.2" style="stroke:var(--fail)" stroke-width="3"/><line x1="311.7" y1="66.7" x2="214.5" y2="72.2" style="stroke:var(--fail)" stroke-width="3"/><circle cx="91.5" cy="77.5" r="5.5" style="fill:var(--accent)"/><circle cx="58.8" cy="37.8" r="5.5" style="fill:var(--accent)"/><circle cx="53.3" cy="98.6" r="5.5" style="fill:var(--accent)"/><circle cx="117.6" cy="95.3" r="5.5" style="fill:var(--accent)"/><circle cx="71.1" cy="90.7" r="5.5" style="fill:var(--accent)"/><path d="M71.5,73 L85.5,87 M71.5,87 L85.5,73" style="stroke:var(--panel)" stroke-width="7" stroke-linecap="round"/><path d="M71.5,73 L85.5,87 M71.5,87 L85.5,73" style="stroke:var(--accent-ink)" stroke-width="3.2" stroke-linecap="round"/><text x="41.3" y="85" text-anchor="end" font-size="13" style="fill:var(--accent-ink)" font-weight="700">μ₁</text><circle cx="302" cy="59.4" r="5.5" style="fill:var(--got)"/><circle cx="333.8" cy="66.3" r="5.5" style="fill:var(--got)"/><circle cx="317.2" cy="76.8" r="5.5" style="fill:var(--got)"/><circle cx="347.2" cy="86.1" r="5.5" style="fill:var(--got)"/><circle cx="269.8" cy="88.2" r="5.5" style="fill:var(--got)"/><circle cx="290.1" cy="41.5" r="5.5" style="fill:var(--got)"/><circle cx="322" cy="48.4" r="5.5" style="fill:var(--got)"/><path d="M304.7,59.7 L318.7,73.7 M304.7,73.7 L318.7,59.7" style="stroke:var(--panel)" stroke-width="7" stroke-linecap="round"/><path d="M304.7,59.7 L318.7,73.7 M304.7,73.7 L318.7,59.7" style="stroke:var(--accent-ink)" stroke-width="3.2" stroke-linecap="round"/><text x="359.2" y="71.7" text-anchor="start" font-size="13" style="fill:var(--accent-ink)" font-weight="700">μ₂</text><rect x="208.5" y="66.2" width="12" height="12" transform="rotate(45 214.5 72.2)" style="fill:var(--fail)"/><text x="214.5" y="58.2" text-anchor="middle" font-size="12" style="fill:var(--fail)" font-weight="700">μ = mean of all</text><text x="20" y="158" text-anchor="start" font-size="12" style="fill:var(--muted)">thin dashed: within (S<tspan baseline-shift="sub" font-size="9">C</tspan>)</text><text x="400" y="158" text-anchor="end" font-size="12" style="fill:var(--fail)" font-weight="700">thick: between (S<tspan baseline-shift="sub" font-size="9">B</tspan>)</text></svg></div>
<p><b>The fact:</b> \(S_T = S_C + S_B\). \(S_T\) is fixed by the data, so whatever \(S_C\) loses, \(S_B\) gains. Minimizing \(S_C\) already maximizes \(S_B\) (for a fixed k): one goal, not two.</p>
<p><b>Extreme:</b> \(k = m\), every sample alone: \(S_C = 0\), \(S_B = S_T\).</p>`,
      formula: R`\[\begin{aligned}S_T &= \sum_{x \in D}\|x - \mu\|^2 = S_C + S_B\\ S_B &= \sum_{i=1}^k n_i\,\|\mu_i - \mu\|^2\end{aligned}\]`,
      remember: R`<p>Not on the sheet: \(S_T = S_C + S_B\), \(S_B\) and \(S_T\). Only WCSS (= \(S_C\)) is.</p>`,
      example: { src: "HW6 Q3 (TSS and relative WCSS)", html: R`<p>For k = 16 the notebook prints WCSS ≈ \(3.82\cdot10^{8}\) and TSS ≈ \(1.236\cdot10^{10}\), where TSS = \(S_T\) (<code>np.sum((X - X.mean(axis=0))**2)</code>). Relative WCSS = WCSS / TSS ≈ 0.031.</p>
<p>Read it with \(S_T = S_C + S_B\): only 3.1% of the color spread is left inside the clusters; the other 96.9% is between the 16 centroid colors. That's why 16 colors already look like the original.</p>` },
      try: { src: "Course summary, p. 110",
        q: R`<p>Show \(S_T = S_C + S_B\). Hint: for a sample in cluster \(C_i\), write \(x - \mu = (x - \mu_i) + (\mu_i - \mu)\).</p>`,
        a: R`<p>Square it (\(\|a + b\|^2 = \|a\|^2 + 2a^\top b + \|b\|^2\)) and add up over the samples of \(C_i\):</p>
\[\begin{aligned}\sum_{x\in C_i}\|x - \mu\|^2 = &\sum_{x\in C_i}\|x - \mu_i\|^2\\ &+ 2\Big(\sum_{x\in C_i}(x - \mu_i)\Big)^{\!\top}(\mu_i - \mu)\\ &+ n_i\,\|\mu_i - \mu\|^2\end{aligned}\]
<p>\((\mu_i - \mu)\) is the same for every sample of \(C_i\), so it comes out of the sum. The sum left in the middle is 0: \(\mu_i\) is the mean of \(C_i\), so the gaps from it cancel out. Add over all clusters: left side = \(S_T\), right side = \(S_C + S_B\).</p>` },
      mistakes: R`<ul><li>\(S_B\) weights each centroid by \(n_i\), its number of samples.</li><li>\(S_C\) alone can't pick k: it's 0 at \(k = m\) (card 8).</li></ul>`,
      where: [] },

    // ───────────────────────── 6 · summary pp. 110–111 + HW6 ─────────────────────────
    { title: "K-means: assign, update",
      what: R`<p>Fix k. Start with k centroids (e.g. k random samples). Repeat until the centroids stop moving:</p>
<p><b>1. Assign:</b> every sample joins its nearest centroid.<br><b>2. Update:</b> every centroid moves to the mean of its samples.</p>
<div class="fig"><svg viewBox="0 0 500 196" width="500" role="img" aria-label="Left, assign: each sample takes the colour of its nearest cross; a dashed line halfway between the two crosses splits them. Right, update: each cross moves, along an arrow, to the mean of its coloured samples"><defs><marker id="clp-a6" viewBox="0 0 10 10" refX="9" refY="5" markerWidth="7" markerHeight="7" orient="auto-start-reverse"><path d="M0,0 L10,5 L0,10 z" style="fill:var(--accent-ink)"/></marker></defs><line x1="77.1" y1="18.1" x2="164.8" y2="160" style="stroke:var(--muted)" stroke-width="1.4" stroke-dasharray="6 4"/><circle cx="64.2" cy="53.3" r="5.5" style="fill:var(--accent)"/><circle cx="80.6" cy="36.1" r="5.5" style="fill:var(--accent)"/><circle cx="81.9" cy="54.8" r="5.5" style="fill:var(--accent)"/><circle cx="55.8" cy="75.6" r="5.5" style="fill:var(--accent)"/><circle cx="45.9" cy="56" r="5.5" style="fill:var(--accent)"/><circle cx="49.1" cy="40.2" r="5.5" style="fill:var(--accent)"/><circle cx="158.1" cy="85.2" r="5.5" style="fill:var(--got)"/><circle cx="142.9" cy="118.5" r="5.5" style="fill:var(--got)"/><circle cx="174.7" cy="127.8" r="5.5" style="fill:var(--got)"/><circle cx="158" cy="125.5" r="5.5" style="fill:var(--got)"/><circle cx="158.7" cy="142.7" r="5.5" style="fill:var(--got)"/><circle cx="178.8" cy="106.6" r="5.5" style="fill:var(--got)"/><path d="M28,133 L42,147 M28,147 L42,133" style="stroke:var(--panel)" stroke-width="7" stroke-linecap="round"/><path d="M28,133 L42,147 M28,147 L42,133" style="stroke:var(--accent)" stroke-width="3.2" stroke-linecap="round"/><path d="M198,28 L212,42 M198,42 L212,28" style="stroke:var(--panel)" stroke-width="7" stroke-linecap="round"/><path d="M198,28 L212,42 M198,42 L212,28" style="stroke:var(--got)" stroke-width="3.2" stroke-linecap="round"/><text x="115" y="186" text-anchor="middle" font-size="12" style="fill:var(--accent-ink)" font-weight="700">1 · assign: nearest ×</text><circle cx="324.2" cy="53.3" r="5.5" style="fill:var(--accent)"/><circle cx="340.6" cy="36.1" r="5.5" style="fill:var(--accent)"/><circle cx="341.9" cy="54.8" r="5.5" style="fill:var(--accent)"/><circle cx="315.8" cy="75.6" r="5.5" style="fill:var(--accent)"/><circle cx="305.9" cy="56" r="5.5" style="fill:var(--accent)"/><circle cx="309.1" cy="40.2" r="5.5" style="fill:var(--accent)"/><circle cx="418.1" cy="85.2" r="5.5" style="fill:var(--got)"/><circle cx="402.9" cy="118.5" r="5.5" style="fill:var(--got)"/><circle cx="434.7" cy="127.8" r="5.5" style="fill:var(--got)"/><circle cx="418" cy="125.5" r="5.5" style="fill:var(--got)"/><circle cx="418.7" cy="142.7" r="5.5" style="fill:var(--got)"/><circle cx="438.8" cy="106.6" r="5.5" style="fill:var(--got)"/><path d="M288,133 L302,147 M288,147 L302,133" style="stroke:var(--panel)" stroke-width="7" stroke-linecap="round"/><path d="M288,133 L302,147 M288,147 L302,133" style="stroke:var(--muted)" stroke-width="3.2" stroke-linecap="round"/><line x1="298" y1="130.5" x2="319.6" y2="63.1" style="stroke:var(--accent-ink)" stroke-width="1.8" marker-end="url(#clp-a6)"/><path d="M315.9,45.7 L329.9,59.7 M315.9,59.7 L329.9,45.7" style="stroke:var(--panel)" stroke-width="7" stroke-linecap="round"/><path d="M315.9,45.7 L329.9,59.7 M315.9,59.7 L329.9,45.7" style="stroke:var(--accent)" stroke-width="3.2" stroke-linecap="round"/><path d="M458,28 L472,42 M458,42 L472,28" style="stroke:var(--panel)" stroke-width="7" stroke-linecap="round"/><path d="M458,28 L472,42 M458,42 L472,28" style="stroke:var(--muted)" stroke-width="3.2" stroke-linecap="round"/><line x1="460.4" y1="43.9" x2="426.9" y2="108" style="stroke:var(--accent-ink)" stroke-width="1.8" marker-end="url(#clp-a6)"/><path d="M414.9,110.7 L428.9,124.7 M414.9,124.7 L428.9,110.7" style="stroke:var(--panel)" stroke-width="7" stroke-linecap="round"/><path d="M414.9,110.7 L428.9,124.7 M414.9,124.7 L428.9,110.7" style="stroke:var(--got)" stroke-width="3.2" stroke-linecap="round"/><text x="375" y="186" text-anchor="middle" font-size="12" style="fill:var(--accent-ink)" font-weight="700">2 · update: × → mean</text><line x1="245" y1="15" x2="245" y2="170" style="stroke:var(--muted)" stroke-width="1" stroke-dasharray="3 4"/></svg></div>
<p><b>Why these two steps:</b> each one is the best move for \(S_C\) with the other half frozen. Centroids fixed → a sample's cheapest home is its nearest centroid. Groups fixed → the point with the smallest squared distances to a group is its mean (card 7). So the centroids get pulled into the middle of the groups they grab.</p>`,
      formula: R`\[\begin{aligned}\text{assign: }&x \to C_i,\ \ i = \arg\min_j \|x - \mu_j\|\\ \text{update: }&\mu_i = \tfrac1{n_i}\textstyle\sum_{x\in C_i} x\end{aligned}\]`,
      remember: R`<p>The loop isn't on the sheet. <b>Empty cluster</b> (a centroid gets no samples, no mean): use k − 1 clusters, pick new random centroids, or split the worst cluster in two. HW6: move it to a random sample.</p>`,
      example: { src: "HW6 Q3 (kmeans, names shortened)", html: R`<pre><code>for it in range(max_iter):
    dist = l_p_dist_from_centroids(X, cents, p)
    assign = np.argmin(dist, axis=0)     # 1. assign
    for j in range(k):
        pix = X[assign == j]
        new[j] = np.mean(pix, axis=0)    # 2. update
    # stop if no centroid moved more than epsilon
    cents = new</code></pre>
<p>If <code>pix</code> is empty, HW6 sets <code>new[j]</code> to a random pixel instead.</p>
<div class="sizecheck"><span class="tag sizetag">Size check</span><p><code>dist</code>: (k, n) → argmin over axis 0 (the centroids) → <code>assign</code>: (n,), one cluster number per pixel ✓</p><p><code>pix</code>: (\(n_j\), 3) → mean over axis 0 → (3,): one color, the new centroid ✓</p></div>` },
      try: { src: "HW6 Q1 (get_random_centroids)",
        q: R`<p>HW6 starts from k <b>different</b> random pixels. What goes wrong if two starting centroids are the same point?</p>`,
        a: R`<p>They're at the same distance from every sample, so <code>np.argmin</code> always picks the first of the two. The second one gets no samples: an empty cluster, with no mean to compute.</p>` },
      mistakes: R`<ul><li>The steps alternate: update with the samples just assigned, then assign again with the <b>new</b> centroids.</li><li>A centroid is a mean, usually not one of the samples.</li></ul>`,
      where: ["2025-A Q2.1", "2025-C Q5.1", "2025-C Q5.2", "2025-C Q5.3", "2025-C Q5.5", "2026-A Q4.1", "2026-A Q4.2", "2026-A Q4.5"] },

    // ───────────────────────── 7 · summary p. 111 ─────────────────────────
    { title: "Convergence and local minima",
      what: R`<p><b>\(S_C\) never goes up.</b> Assign: a sample only moves if another centroid is closer, so its term shrinks. Update: the mean is the point with the smallest squared distances to its group.</p>
<p>There are only finitely many ways to assign the samples, and \(S_C \ge 0\). A number that never goes up and has finitely many possible values must stop changing: <b>K-means always converges</b>.</p>
<div class="fig"><svg viewBox="0 0 480 188" width="480" role="img" aria-label="The same three groups twice. Left: one cross in the middle of each group. Right: one cross sits between the two left groups and two crosses split the right group; no step of K-means changes this"><circle cx="60.5" cy="55" r="5.5" style="fill:var(--accent)"/><circle cx="55.8" cy="34.2" r="5.5" style="fill:var(--accent)"/><circle cx="82.2" cy="53.9" r="5.5" style="fill:var(--accent)"/><circle cx="76.9" cy="38.9" r="5.5" style="fill:var(--accent)"/><circle cx="46.5" cy="49.9" r="5.5" style="fill:var(--accent)"/><circle cx="58.7" cy="138" r="5.5" style="fill:var(--got)"/><circle cx="67.9" cy="111.6" r="5.5" style="fill:var(--got)"/><circle cx="84.8" cy="133.5" r="5.5" style="fill:var(--got)"/><circle cx="69.3" cy="126.5" r="5.5" style="fill:var(--got)"/><circle cx="49" cy="124.7" r="5.5" style="fill:var(--got)"/><circle cx="151.2" cy="83.9" r="5.5" style="fill:var(--shaky)"/><circle cx="164.2" cy="110.2" r="5.5" style="fill:var(--shaky)"/><circle cx="169.4" cy="74.6" r="5.5" style="fill:var(--shaky)"/><circle cx="183.7" cy="88.2" r="5.5" style="fill:var(--shaky)"/><circle cx="165.6" cy="92.8" r="5.5" style="fill:var(--shaky)"/><path d="M57.4,39.4 L71.4,53.4 M57.4,53.4 L71.4,39.4" style="stroke:var(--panel)" stroke-width="7" stroke-linecap="round"/><path d="M57.4,39.4 L71.4,53.4 M57.4,53.4 L71.4,39.4" style="stroke:var(--accent-ink)" stroke-width="3.2" stroke-linecap="round"/><path d="M58.9,119.9 L72.9,133.9 M58.9,133.9 L72.9,119.9" style="stroke:var(--panel)" stroke-width="7" stroke-linecap="round"/><path d="M58.9,119.9 L72.9,133.9 M58.9,133.9 L72.9,119.9" style="stroke:var(--accent-ink)" stroke-width="3.2" stroke-linecap="round"/><path d="M159.8,83 L173.8,97 M159.8,97 L173.8,83" style="stroke:var(--panel)" stroke-width="7" stroke-linecap="round"/><path d="M159.8,83 L173.8,97 M159.8,97 L173.8,83" style="stroke:var(--accent-ink)" stroke-width="3.2" stroke-linecap="round"/><text x="115" y="178" text-anchor="middle" font-size="12" style="fill:var(--got)" font-weight="700">best: S<tspan baseline-shift="sub" font-size="9">C</tspan> smallest</text><circle cx="315.5" cy="55" r="5.5" style="fill:var(--accent)"/><circle cx="310.8" cy="34.2" r="5.5" style="fill:var(--accent)"/><circle cx="337.2" cy="53.9" r="5.5" style="fill:var(--accent)"/><circle cx="331.9" cy="38.9" r="5.5" style="fill:var(--accent)"/><circle cx="301.5" cy="49.9" r="5.5" style="fill:var(--accent)"/><circle cx="313.7" cy="138" r="5.5" style="fill:var(--accent)"/><circle cx="322.9" cy="111.6" r="5.5" style="fill:var(--accent)"/><circle cx="339.8" cy="133.5" r="5.5" style="fill:var(--accent)"/><circle cx="324.3" cy="126.5" r="5.5" style="fill:var(--accent)"/><circle cx="304" cy="124.7" r="5.5" style="fill:var(--accent)"/><circle cx="406.2" cy="83.9" r="5.5" style="fill:var(--got)"/><circle cx="419.2" cy="110.2" r="5.5" style="fill:var(--shaky)"/><circle cx="424.4" cy="74.6" r="5.5" style="fill:var(--got)"/><circle cx="438.7" cy="88.2" r="5.5" style="fill:var(--got)"/><circle cx="420.6" cy="92.8" r="5.5" style="fill:var(--shaky)"/><path d="M313.2,79.6 L327.2,93.6 M313.2,93.6 L327.2,79.6" style="stroke:var(--panel)" stroke-width="7" stroke-linecap="round"/><path d="M313.2,79.6 L327.2,93.6 M313.2,93.6 L327.2,79.6" style="stroke:var(--accent-ink)" stroke-width="3.2" stroke-linecap="round"/><path d="M416.1,75.2 L430.1,89.2 M416.1,89.2 L430.1,75.2" style="stroke:var(--panel)" stroke-width="7" stroke-linecap="round"/><path d="M416.1,75.2 L430.1,89.2 M416.1,89.2 L430.1,75.2" style="stroke:var(--accent-ink)" stroke-width="3.2" stroke-linecap="round"/><path d="M412.9,94.5 L426.9,108.5 M412.9,108.5 L426.9,94.5" style="stroke:var(--panel)" stroke-width="7" stroke-linecap="round"/><path d="M412.9,94.5 L426.9,108.5 M412.9,108.5 L426.9,94.5" style="stroke:var(--accent-ink)" stroke-width="3.2" stroke-linecap="round"/><text x="370" y="178" text-anchor="middle" font-size="12" style="fill:var(--fail)" font-weight="700">stuck: a local minimum</text><line x1="245" y1="15" x2="245" y2="160" style="stroke:var(--muted)" stroke-width="1" stroke-dasharray="3 4"/></svg></div>
<p><b>But maybe to a local minimum.</b> Where it stops depends on the starting centroids; once stuck, no step changes anything. Fix: run it several times from different random starts, keep the run with the smallest \(S_C\).</p>`,
      formula: R`\[S_C\ \text{after a step} \;\le\; S_C\ \text{before it}\]`,
      remember: R`<p>The mean is the point with the smallest sum of squared distances to its group (the example shows why). K-means always converges, but not always to the smallest \(S_C\). Not on the sheet.</p>`,
      example: { src: "Course summary, p. 111 ('center of mass minimizes second moment')", html: R`<p>One cluster, one feature. Which point \(c\) makes \(\sum_x (x - c)^2\) smallest?</p>
<p><b>Derivative by c</b> — chain rule per sample, like \((3 - c)^2 \to 2(3 - c)\cdot(-1)\):</p>
\[\frac{d}{dc}\sum_x (x - c)^2 = \sum_x 2(x - c)\cdot(-1) = -2\sum_x (x - c)\]
<p><b>Set it to 0:</b> \(\sum_x x - n\,c = 0\) → \(c = \frac1n\sum_x x\): the mean. (Second derivative \(2n \gt 0\): a minimum.)</p>
<p>With more features, \(\|x - c\|^2\) is a sum over the features, and each feature gives its own copy of this. So \(c\) = the mean in every feature = \(\mu_i\).</p>` },
      try: { src: "Course summary, p. 111 (the 'local optima' figure)",
        q: R`<p>In the stuck picture, one centroid sits between two groups and two centroids share the third group. Why can't more K-means steps fix it?</p>`,
        a: R`<p><b>Assign:</b> every sample is already nearest to its own centroid, so nobody moves. <b>Update:</b> each centroid already is the mean of its samples, so no centroid moves. Nothing changes: K-means has converged, with a bigger \(S_C\) than the best clustering. Only a new start can escape.</p>` },
      mistakes: R`<ul><li>"Converges" ≠ "finds the smallest \(S_C\)".</li><li>Same starting centroids → same result: after the start, K-means has no randomness.</li></ul>`,
      where: ["2025-A Q2.1", "2025-C Q5.2", "2026-A Q4.2", "2026-A Q4.3"] },

    // ───────────────────────── 8 · summary p. 112 + HW6 ─────────────────────────
    { title: "Choosing k: the elbow",
      what: R`<p>Why not pick the k with the smallest \(S_C\)? Because \(S_C\) keeps dropping as k grows: more centroids, every sample closer to one. At \(k = m\) every sample is alone and \(S_C = 0\): a perfect score for a useless clustering.</p>
<p>No method knows the best k for sure. <b>Heuristic:</b> run K-means for k = 1, 2, 3, … and plot \(S_C\) against k.</p>
<div class="fig"><svg viewBox="0 0 420 200" width="420" role="img" aria-label="S_C against k: it drops fast from k = 1 to k = 4, then only a little for every further k; the bend at k = 4 is circled as the elbow"><line x1="60" y1="160" x2="410" y2="160" style="stroke:var(--muted)" stroke-width="1.5"/><line x1="60" y1="160" x2="60" y2="15" style="stroke:var(--muted)" stroke-width="1.5"/><line x1="60" y1="160" x2="60" y2="164" style="stroke:var(--muted)" stroke-width="1.5"/><text x="60" y="177" text-anchor="middle" font-size="11" style="fill:var(--muted)">1</text><line x1="108.6" y1="160" x2="108.6" y2="164" style="stroke:var(--muted)" stroke-width="1.5"/><text x="108.6" y="177" text-anchor="middle" font-size="11" style="fill:var(--muted)">2</text><line x1="157.1" y1="160" x2="157.1" y2="164" style="stroke:var(--muted)" stroke-width="1.5"/><text x="157.1" y="177" text-anchor="middle" font-size="11" style="fill:var(--muted)">3</text><line x1="205.7" y1="160" x2="205.7" y2="164" style="stroke:var(--muted)" stroke-width="1.5"/><text x="205.7" y="177" text-anchor="middle" font-size="11" style="fill:var(--muted)">4</text><line x1="254.3" y1="160" x2="254.3" y2="164" style="stroke:var(--muted)" stroke-width="1.5"/><text x="254.3" y="177" text-anchor="middle" font-size="11" style="fill:var(--muted)">5</text><line x1="302.9" y1="160" x2="302.9" y2="164" style="stroke:var(--muted)" stroke-width="1.5"/><text x="302.9" y="177" text-anchor="middle" font-size="11" style="fill:var(--muted)">6</text><line x1="351.4" y1="160" x2="351.4" y2="164" style="stroke:var(--muted)" stroke-width="1.5"/><text x="351.4" y="177" text-anchor="middle" font-size="11" style="fill:var(--muted)">7</text><line x1="400" y1="160" x2="400" y2="164" style="stroke:var(--muted)" stroke-width="1.5"/><text x="400" y="177" text-anchor="middle" font-size="11" style="fill:var(--muted)">8</text><polyline points="60,25 108.6,84.4 157.1,116.8 205.7,142.4 254.3,146.5 302.9,149.2 351.4,151.2 400,152.6" style="fill:none;stroke:var(--accent)" stroke-width="2.5"/><circle cx="60" cy="25" r="4" style="fill:var(--accent)"/><circle cx="108.6" cy="84.4" r="4" style="fill:var(--accent)"/><circle cx="157.1" cy="116.8" r="4" style="fill:var(--accent)"/><circle cx="205.7" cy="142.4" r="4" style="fill:var(--accent)"/><circle cx="254.3" cy="146.5" r="4" style="fill:var(--accent)"/><circle cx="302.9" cy="149.2" r="4" style="fill:var(--accent)"/><circle cx="351.4" cy="151.2" r="4" style="fill:var(--accent)"/><circle cx="400" cy="152.6" r="4" style="fill:var(--accent)"/><circle cx="205.7" cy="142.4" r="11" style="fill:none;stroke:var(--fail)" stroke-width="2"/><text x="221.7" y="126.4" text-anchor="start" font-size="12" style="fill:var(--fail)" font-weight="700">elbow</text><text x="122.6" y="82.4" text-anchor="start" font-size="11" style="fill:var(--accent-ink)">big drops</text><text x="312.6" y="133.2" text-anchor="middle" font-size="11" style="fill:var(--muted)">small drops</text><text x="408" y="192" text-anchor="end" font-size="12" fill="currentColor">k</text><text x="22" y="92.5" text-anchor="middle" font-size="12" fill="currentColor" transform="rotate(-90 22 92.5)">S<tspan baseline-shift="sub" font-size="9">C</tspan></text></svg></div>
<p><b>The elbow:</b> the k after which one more cluster barely helps. Before it, a new cluster splits a real group off: big drop. After it, it only cuts a tight group in two: small drop.</p>`,
      formula: R`\[\Delta S_C = S_C(k) - S_C(k+1)\]<p>Big before the elbow, small after.</p>`,
      example: { src: "HW6 Q3 (relative WCSS for k = 1 … 16)", html: R`<p>HW6 runs K-means on the image for k = 1 … 16, plots WCSS / TSS against k, and asks "Do you notice an elbow?"</p>
<p>Read off the plot: 1 at k = 1, about 0.38 at k = 2, 0.27 at k = 3, 0.14 at k = 4, then only small drops, down to 0.03 at k = 16. The elbow is around k = 4.</p>` },
      try: { src: "HW6 Q3",
        q: R`<p>Why is WCSS / TSS exactly 1 at k = 1?</p>`,
        a: R`<p>One cluster holds every sample, so its centroid is the mean of all the data: \(\mu_1 = \mu\). Then \(S_C = \sum_x\|x - \mu\|^2 = S_T\) (and \(S_B = 0\)).</p>` },
      mistakes: R`<ul><li>Picking the k with the smallest \(S_C\): that's always the biggest k.</li><li>The elbow is a heuristic; it doesn't guarantee the best k.</li></ul>`,
      where: ["2025-A Q2.3"] },

    // ───────────────────────── 9 · summary pp. 112–113 ─────────────────────────
    { title: "The silhouette",
      what: R`<p>A score per sample: is it in a good cluster? For \(x\) in cluster \(C_i\):</p>
<p>\(a(x)\) = the average distance from \(x\) to its own cluster (want small).<br>\(b(x)\) = the average distance to the <b>nearest other</b> cluster (want big).</p>
<div class="fig"><svg viewBox="0 0 470 142" width="470" role="img" aria-label="A sample x with solid lines to the other samples of its own cluster (their average length is a) and dashed lines to the samples of the nearest other cluster (average length b); a third, farther cluster is ignored"><line x1="115" y1="50" x2="83.7" y2="59.2" style="stroke:var(--accent)" stroke-width="1.6"/><line x1="115" y1="50" x2="58" y2="84.6" style="stroke:var(--accent)" stroke-width="1.6"/><line x1="115" y1="50" x2="63.1" y2="47.4" style="stroke:var(--accent)" stroke-width="1.6"/><line x1="115" y1="50" x2="97.5" y2="41.3" style="stroke:var(--accent)" stroke-width="1.6"/><line x1="115" y1="50" x2="250.6" y2="33.2" style="stroke:var(--got)" stroke-width="1.3" stroke-dasharray="5 4"/><line x1="115" y1="50" x2="249.7" y2="67.6" style="stroke:var(--got)" stroke-width="1.3" stroke-dasharray="5 4"/><line x1="115" y1="50" x2="238.8" y2="50.1" style="stroke:var(--got)" stroke-width="1.3" stroke-dasharray="5 4"/><line x1="115" y1="50" x2="213.5" y2="51.7" style="stroke:var(--got)" stroke-width="1.3" stroke-dasharray="5 4"/><line x1="115" y1="50" x2="222" y2="76" style="stroke:var(--got)" stroke-width="1.3" stroke-dasharray="5 4"/><circle cx="83.7" cy="59.2" r="5.5" style="fill:var(--accent)"/><circle cx="58" cy="84.6" r="5.5" style="fill:var(--accent)"/><circle cx="63.1" cy="47.4" r="5.5" style="fill:var(--accent)"/><circle cx="97.5" cy="41.3" r="5.5" style="fill:var(--accent)"/><circle cx="250.6" cy="33.2" r="5.5" style="fill:var(--got)"/><circle cx="249.7" cy="67.6" r="5.5" style="fill:var(--got)"/><circle cx="238.8" cy="50.1" r="5.5" style="fill:var(--got)"/><circle cx="213.5" cy="51.7" r="5.5" style="fill:var(--got)"/><circle cx="222" cy="76" r="5.5" style="fill:var(--got)"/><circle cx="414.7" cy="86.6" r="5.5" style="fill:var(--shaky)"/><circle cx="391.7" cy="90.9" r="5.5" style="fill:var(--shaky)"/><circle cx="404.3" cy="102.8" r="5.5" style="fill:var(--shaky)"/><circle cx="402.2" cy="71.4" r="5.5" style="fill:var(--shaky)"/><circle cx="115" cy="50" r="8" style="fill:var(--accent);stroke:var(--accent-ink)" stroke-width="3"/><text x="113" y="34" text-anchor="middle" font-size="14" fill="currentColor" font-weight="700">x</text><text x="85" y="130" text-anchor="middle" font-size="12" style="fill:var(--accent-ink)" font-weight="700">a(x): own cluster</text><text x="255" y="130" text-anchor="middle" font-size="12" style="fill:var(--got)" font-weight="700">b(x): nearest other</text><text x="400" y="130" text-anchor="middle" font-size="12" style="fill:var(--muted)">farther: skip</text></svg></div>
<p><b>Why \(\frac{b - a}{\max\{a, b\}}\):</b> \(b - a \gt 0\) means \(x\) is closer to its own cluster than to the next one. Dividing by the bigger of the two gives a number in [−1, 1], whatever the units. ≈ 1: well placed (\(a \ll b\)). 0: on the border (\(a = b\)). Negative: probably in the wrong cluster.</p>`,
      formula: R`\[\begin{aligned}S(x) &= \frac{b(x) - a(x)}{\max\{a(x), b(x)\}} \in [-1, 1]\\ SC &= \frac1m\sum_{x\in D}S(x)\end{aligned}\]<p>SC: one score for the whole clustering, bigger = better.</p>`,
      remember: R`\[\begin{aligned}a(x) &= \bar d(x, C_i),\qquad b(x) = \min_{j \ne i}\,\bar d(x, C_j)\\ \bar d(x, C) &= \frac{1}{|C|}\sum_{y \in C} d(x, y)\end{aligned}\]<p>Not on the sheet. The summary's \(a(x)\) divides by \(|C_i|\), counting \(x\) itself (distance 0); many texts divide by \(|C_i| - 1\). If a question defines it, use theirs.</p>`,
      mistakes: R`<ul><li>\(b(x)\) uses only the <b>nearest</b> other cluster, not all of them.</li><li>Divide by the <b>bigger</b> of a and b, not always by b.</li></ul>`,
      where: [] },

    // ───────────────────────── 10 · summary p. 113 ─────────────────────────
    { title: "Soft K-means",
      what: R`<p>K-means puts every sample in exactly one cluster, even one right between two centroids. <b>Soft K-means</b> gives it a bit of each: a membership per cluster.</p>
<p>Turn distance into membership with \(e^{-\|x - \mu_i\|^2}\): distance 0 → 1, far → almost 0.</p>
<div class="fig"><svg viewBox="0 0 440 182" width="440" role="img" aria-label="A bell around each center: its height is e to the minus squared distance, 1 at the center. A sample x between the centers reads the height of each bell above it: 0.37 for the nearer center, 0.11 for the other"><line x1="30" y1="150" x2="435" y2="150" style="stroke:var(--muted)" stroke-width="1.5"/><polyline points="30,150 32.2,150 34.5,150 36.8,150 39,150 41.2,149.9 43.5,149.9 45.8,149.9 48,149.9 50.2,149.8 52.5,149.8 54.8,149.7 57,149.7 59.2,149.6 61.5,149.4 63.8,149.3 66,149.1 68.2,148.9 70.5,148.7 72.8,148.4 75,148 77.2,147.5 79.5,147 81.8,146.4 84,145.7 86.2,144.9 88.5,143.9 90.8,142.8 93,141.5 95.3,140 97.5,138.4 99.8,136.6 102,134.5 104.2,132.2 106.5,129.7 108.8,126.9 111,123.9 113.2,120.7 115.5,117.2 117.8,113.5 120,109.5 122.3,105.4 124.5,101.1 126.8,96.6 129,92 131.2,87.3 133.5,82.6 135.8,77.9 138,73.3 140.2,68.7 142.5,64.3 144.8,60.2 147,56.3 149.2,52.7 151.5,49.5 153.8,46.7 156,44.3 158.2,42.4 160.5,41.1 162.8,40.3 165,40 167.2,40.3 169.5,41.1 171.8,42.4 174,44.3 176.2,46.7 178.5,49.5 180.8,52.7 183,56.3 185.2,60.2 187.5,64.3 189.8,68.7 192,73.3 194.3,77.9 196.5,82.6 198.8,87.3 201,92 203.2,96.6 205.5,101.1 207.8,105.4 210,109.5 212.2,113.5 214.5,117.2 216.8,120.7 219,123.9 221.2,126.9 223.5,129.7 225.8,132.2 228,134.5 230.2,136.6 232.5,138.4 234.8,140 237,141.5 239.3,142.8 241.5,143.9 243.8,144.9 246,145.7 248.3,146.4 250.5,147 252.8,147.5 255,148 257.2,148.4 259.5,148.7 261.8,148.9 264,149.1 266.2,149.3 268.5,149.4 270.8,149.6 273,149.7 275.2,149.7 277.5,149.8 279.8,149.8 282,149.9 284.2,149.9 286.5,149.9 288.8,149.9 291,150 293.2,150 295.5,150 297.8,150 300,150" style="fill:none;stroke:var(--accent)" stroke-width="2.5"/><path d="M158,143 L172,157 M158,157 L172,143" style="stroke:var(--panel)" stroke-width="7" stroke-linecap="round"/><path d="M158,143 L172,157 M158,157 L172,143" style="stroke:var(--accent)" stroke-width="3.2" stroke-linecap="round"/><polyline points="142.5,150 144.8,150 147,150 149.2,150 151.5,150 153.8,149.9 156,149.9 158.2,149.9 160.5,149.9 162.8,149.8 165,149.8 167.2,149.7 169.5,149.7 171.8,149.6 174,149.4 176.2,149.3 178.5,149.1 180.8,148.9 183,148.7 185.2,148.4 187.5,148 189.8,147.5 192,147 194.3,146.4 196.5,145.7 198.8,144.9 201,143.9 203.2,142.8 205.5,141.5 207.8,140 210,138.4 212.2,136.6 214.5,134.5 216.8,132.2 219,129.7 221.2,126.9 223.5,123.9 225.7,120.7 228,117.2 230.2,113.5 232.5,109.5 234.8,105.4 237,101.1 239.3,96.6 241.5,92 243.8,87.3 246,82.6 248.2,77.9 250.5,73.3 252.8,68.7 255,64.3 257.2,60.2 259.5,56.3 261.8,52.7 264,49.5 266.2,46.7 268.5,44.3 270.8,42.4 273,41.1 275.2,40.3 277.5,40 279.8,40.3 282,41.1 284.2,42.4 286.5,44.3 288.8,46.7 291,49.5 293.2,52.7 295.5,56.3 297.8,60.2 300,64.3 302.3,68.7 304.5,73.3 306.8,77.9 309,82.6 311.2,87.3 313.5,92 315.8,96.6 318,101.1 320.2,105.4 322.5,109.5 324.8,113.5 327,117.2 329.2,120.7 331.5,123.9 333.8,126.9 336,129.7 338.2,132.2 340.5,134.5 342.8,136.6 345,138.4 347.2,140 349.5,141.5 351.8,142.8 354,143.9 356.2,144.9 358.5,145.7 360.8,146.4 363,147 365.2,147.5 367.5,148 369.8,148.4 372,148.7 374.2,148.9 376.5,149.1 378.8,149.3 381,149.4 383.2,149.6 385.5,149.7 387.8,149.7 390,149.8 392.3,149.8 394.5,149.9 396.8,149.9 399,149.9 401.2,149.9 403.5,150 405.8,150 408,150 410.2,150 412.5,150" style="fill:none;stroke:var(--got)" stroke-width="2.5"/><path d="M270.5,143 L284.5,157 M270.5,157 L284.5,143" style="stroke:var(--panel)" stroke-width="7" stroke-linecap="round"/><path d="M270.5,143 L284.5,157 M270.5,157 L284.5,143" style="stroke:var(--got)" stroke-width="3.2" stroke-linecap="round"/><line x1="210" y1="150" x2="210" y2="35" style="stroke:var(--muted)" stroke-width="1.2" stroke-dasharray="4 3"/><circle cx="210" cy="109.5" r="5" style="fill:var(--accent)"/><circle cx="210" cy="138.4" r="5" style="fill:var(--got)"/><text x="438" y="24" text-anchor="end" font-size="12" style="fill:var(--accent-ink)" font-weight="700">bell 1 above x: 0.37</text><text x="438" y="42" text-anchor="end" font-size="12" style="fill:var(--got)" font-weight="700">bell 2 above x: 0.11</text><circle cx="210" cy="150" r="6" style="fill:var(--panel);stroke:currentColor" stroke-width="2"/><text x="210" y="172" text-anchor="middle" font-size="13" fill="currentColor" font-weight="700">x</text><text x="165" y="172" text-anchor="middle" font-size="12" style="fill:var(--accent-ink)" font-weight="700">μ₁</text><text x="277.5" y="172" text-anchor="middle" font-size="12" style="fill:var(--got)" font-weight="700">μ₂</text><text x="135" y="36" text-anchor="end" font-size="11" style="fill:var(--muted)">height 1 at μ₁</text></svg></div>
<p><b>Picture:</b> a bell around every centroid; \(x\)'s membership in cluster i = the height of bell i above \(x\).</p>
<p>Same loop as K-means, two changes. <b>Assign:</b> compute all k memberships, the list \(v(x)\). <b>Update:</b> a weighted mean: each sample pulls \(\mu_i\) as much as its membership in i. Hard answer at the end: the biggest membership.</p>`,
      formula: R`\[\begin{aligned}v(x) &= \big(e^{-\|x - \mu_1\|^2}, \dots, e^{-\|x - \mu_k\|^2}\big)\\ \mu_i &= \frac{\sum_{x\in D} v_i(x)\,x}{\sum_{x\in D} v_i(x)}\\ j^* &= \arg\max_j\ v_j\end{aligned}\]`,
      remember: R`<p>Not on the sheet. Optional: normalize, \(v / \|v\|\) (entries adding up to 1); then \(v_j\) = the probability that \(x\) is in cluster j, like the GMM responsibilities.</p>`,
      try: { src: "Course summary, p. 113 ('weighted mean vs. simple mean')",
        q: R`<p>Suppose every membership were only 1 (for the nearest centroid) or 0 (for all the others). What does the weighted-mean update become?</p>`,
        a: R`<p>The top adds up only the samples with membership 1 in cluster i, and the bottom counts them: \(n_i\). So \(\mu_i = \frac1{n_i}\sum_{x\in C_i} x\): plain K-means. Soft K-means just replaces the 0/1 with numbers in between.</p>` },
      mistakes: R`<ul><li>Divide by the <b>sum of the memberships</b>, not by the number of samples.</li><li>The exponent is minus the <b>squared</b> distance.</li></ul>`,
      where: [] },

    // ───────────────────────── 11 · summary p. 114 ─────────────────────────
    { title: "Hierarchical clustering",
      what: R`<p>K-means needs k up front. Hierarchical clustering builds a whole ladder of clusterings, from m clusters down to 1.</p>
<p><b>Bottom-up (agglomerative):</b> start with every sample in its own cluster. Each step, merge the two <b>closest</b> clusters. Stop when one cluster holds everything.</p>
<div class="fig"><svg viewBox="0 0 440 230" width="440" role="img" aria-label="Five samples. Dashed boxes show the merges in order: first samples 4 and 5, then 3 joins them, then 1 and 2, and finally everything is one cluster"><rect x="314.8" y="105.5" width="47" height="26" rx="14" style="fill:none;stroke:var(--accent-ink)" stroke-width="1.6" stroke-dasharray="5 3"/><text x="318.8" y="100.5" text-anchor="start" font-size="11" style="fill:var(--accent-ink)" font-weight="700">1st</text><rect x="227" y="48.5" width="149.8" height="98" rx="14" style="fill:none;stroke:var(--got)" stroke-width="1.6" stroke-dasharray="5 3"/><text x="231" y="43.5" text-anchor="start" font-size="11" style="fill:var(--got)" font-weight="700">2nd</text><rect x="44" y="60.5" width="107" height="105.5" rx="14" style="fill:none;stroke:var(--shaky)" stroke-width="1.6" stroke-dasharray="5 3"/><text x="48" y="55.5" text-anchor="start" font-size="11" style="fill:var(--shaky)" font-weight="700">3rd</text><rect x="14" y="30.5" width="380.8" height="165.5" rx="14" style="fill:none;stroke:var(--muted)" stroke-width="1.6" stroke-dasharray="5 3"/><text x="18" y="25.5" text-anchor="start" font-size="11" style="fill:var(--muted)" font-weight="700">4th: all</text><circle cx="60" cy="150" r="9" style="fill:var(--accent)"/><text x="60" y="154" text-anchor="middle" font-size="11" style="fill:var(--panel)" font-weight="700">1</text><circle cx="135" cy="76.5" r="9" style="fill:var(--accent)"/><text x="135" y="80.5" text-anchor="middle" font-size="11" style="fill:var(--panel)" font-weight="700">2</text><circle cx="255" cy="76.5" r="9" style="fill:var(--accent)"/><text x="255" y="80.5" text-anchor="middle" font-size="11" style="fill:var(--panel)" font-weight="700">3</text><circle cx="327.8" cy="118.5" r="9" style="fill:var(--accent)"/><text x="327.8" y="122.5" text-anchor="middle" font-size="11" style="fill:var(--panel)" font-weight="700">4</text><circle cx="348.8" cy="118.5" r="9" style="fill:var(--accent)"/><text x="348.8" y="122.5" text-anchor="middle" font-size="11" style="fill:var(--panel)" font-weight="700">5</text></svg></div>
<p><b>Top-down (divisive):</b> the other way round. Start with one cluster of everything; each step, split the least compact cluster in two.</p>
<p>"Closest clusters" needs a distance between <b>groups</b> of samples, not just between two samples: next card. The merges drawn as a tree: the dendrogram (card 13).</p>`,
      formula: R`\[m \text{ clusters} \to m - 1 \to \dots \to 1:\quad m - 1 \text{ merges}\]`,
      remember: R`<p>Keep a table of the distances between all current clusters. Each step: merge the closest pair, then update the table; only the new cluster's row and column change. Not on the sheet.</p>`,
      mistakes: R`<ul><li>One merge per step: always the single closest pair of clusters.</li></ul>`,
      where: ["2025-A Q2.4", "2025-A Q2.5", "2026-A Q4.4"] },

    // ───────────────────────── 12 · summary p. 115 ─────────────────────────
    { title: "Distance between clusters",
      what: R`<p>Clusters R and Q are groups of samples. How far apart are they? Four options, all built on the sample distance \(d(x, y)\):</p>
<div class="fig"><svg viewBox="0 0 420 196" width="420" role="img" aria-label="Two clusters R and Q. A thick solid line joins their closest pair (single linkage), a dashed line their farthest pair (complete linkage), and a dotted line their two centers (means distance)"><line x1="70" y1="70" x2="345" y2="110" style="stroke:var(--fail)" stroke-width="2" stroke-dasharray="7 4"/><line x1="98.8" y1="77.5" x2="311.2" y2="80" style="stroke:var(--muted)" stroke-width="1.6" stroke-dasharray="2 3"/><line x1="130" y1="85" x2="270" y2="60" style="stroke:var(--got)" stroke-width="3"/><circle cx="70" cy="70" r="6" style="fill:var(--accent)"/><circle cx="100" cy="50" r="6" style="fill:var(--accent)"/><circle cx="95" cy="105" r="6" style="fill:var(--accent)"/><circle cx="130" cy="85" r="6" style="fill:var(--accent)"/><circle cx="270" cy="60" r="6" style="fill:var(--shaky)"/><circle cx="300" cy="95" r="6" style="fill:var(--shaky)"/><circle cx="330" cy="55" r="6" style="fill:var(--shaky)"/><circle cx="345" cy="110" r="6" style="fill:var(--shaky)"/><path d="M92.8,71.5 L104.8,83.5 M92.8,83.5 L104.8,71.5" style="stroke:var(--panel)" stroke-width="7" stroke-linecap="round"/><path d="M92.8,71.5 L104.8,83.5 M92.8,83.5 L104.8,71.5" style="stroke:var(--accent-ink)" stroke-width="3.2" stroke-linecap="round"/><path d="M305.2,74 L317.2,86 M305.2,86 L317.2,74" style="stroke:var(--panel)" stroke-width="7" stroke-linecap="round"/><path d="M305.2,74 L317.2,86 M305.2,86 L317.2,74" style="stroke:var(--shaky)" stroke-width="3.2" stroke-linecap="round"/><text x="95" y="22" text-anchor="middle" font-size="14" style="fill:var(--accent-ink)" font-weight="700">R</text><text x="308" y="22" text-anchor="middle" font-size="14" style="fill:var(--shaky)" font-weight="700">Q</text><text x="200" y="150" text-anchor="middle" font-size="12" style="fill:var(--got)" font-weight="700">single = shortest pair</text><text x="200" y="168" text-anchor="middle" font-size="12" style="fill:var(--fail)" font-weight="700">complete = longest pair</text><text x="200" y="186" text-anchor="middle" font-size="12" style="fill:var(--muted)" font-weight="700">means = center to center</text></svg></div>
<p><b>Single linkage:</b> the closest pair. <b>Complete linkage:</b> the farthest pair. <b>Average:</b> the average over all pairs (one sample from each). <b>Means:</b> centroid to centroid.</p>
<p><b>Why it matters:</b> single linkage needs just one close pair to merge, so it can chain samples into long snakes. Complete linkage needs every pair close, so it prefers compact clusters. Same data, different merges.</p>`,
      formula: R`\[\begin{aligned}\text{single: } D(R, Q) &= \min_{x\in R,\,y\in Q} d(x, y)\\ \text{complete: } D(R, Q) &= \max_{x\in R,\,y\in Q} d(x, y)\\ \text{average: } D(R, Q) &= \frac{1}{n_Rn_Q}\sum_{x\in R,\,y\in Q} d(x, y)\\ \text{means: } D(R, Q) &= \|\mu_R - \mu_Q\|\end{aligned}\]`,
      remember: R`<p>Not on the sheet. After merging R and Q, the new row of the table, for any other cluster S: single → \(\min\{D(R, S), D(Q, S)\}\), complete → \(\max\{D(R, S), D(Q, S)\}\). (The closest pair from R∪Q to S is the closer of the two old closest pairs.)</p>`,
      mistakes: R`<ul><li>Complete linkage still merges the two clusters with the <b>smallest</b> D; the max is only inside D.</li><li>Single = min, complete = max: easy to swap.</li></ul>`,
      where: ["2025-A Q2.4", "2025-A Q2.5", "2026-A Q4.4"] },

    // ───────────────────────── 13 · summary p. 115 ─────────────────────────
    { title: "The dendrogram: choosing k",
      what: R`<p>The merge history as a tree. Samples along the bottom; each merge is a bar joining two branches, at <b>height = the distance</b> at which they merged.</p>
<div class="fig"><svg viewBox="0 0 480 226" width="480" role="img" aria-label="A dendrogram of five samples: 4 and 5 merge at height 0.14, 3 joins them at 0.56, 1 and 2 merge at 0.7, everything at 0.8. A dashed cut at height 0.63 crosses three vertical branches, giving the clusters 1, 2, and 3-4-5"><line x1="70" y1="200" x2="70" y2="15" style="stroke:var(--muted)" stroke-width="1.5"/><line x1="66" y1="200" x2="70" y2="200" style="stroke:var(--muted)" stroke-width="1.5"/><text x="63" y="204" text-anchor="end" font-size="11" style="fill:var(--muted)">0</text><line x1="66" y1="156.5" x2="70" y2="156.5" style="stroke:var(--muted)" stroke-width="1.5"/><text x="63" y="160.5" text-anchor="end" font-size="11" style="fill:var(--muted)">0.2</text><line x1="66" y1="112.9" x2="70" y2="112.9" style="stroke:var(--muted)" stroke-width="1.5"/><text x="63" y="116.9" text-anchor="end" font-size="11" style="fill:var(--muted)">0.4</text><line x1="66" y1="69.4" x2="70" y2="69.4" style="stroke:var(--muted)" stroke-width="1.5"/><text x="63" y="73.4" text-anchor="end" font-size="11" style="fill:var(--muted)">0.6</text><line x1="66" y1="25.9" x2="70" y2="25.9" style="stroke:var(--muted)" stroke-width="1.5"/><text x="63" y="29.9" text-anchor="end" font-size="11" style="fill:var(--muted)">0.8</text><text x="20" y="108.6" text-anchor="middle" font-size="11" style="fill:var(--muted)" transform="rotate(-90 20 108.6)">merge distance</text><line x1="245" y1="200" x2="245" y2="169.5" style="stroke:var(--accent)" stroke-width="2.2"/><line x1="295" y1="200" x2="295" y2="169.5" style="stroke:var(--accent)" stroke-width="2.2"/><line x1="245" y1="169.5" x2="295" y2="169.5" style="stroke:var(--accent)" stroke-width="2.2"/><line x1="195" y1="200" x2="195" y2="78.1" style="stroke:var(--accent)" stroke-width="2.2"/><line x1="270" y1="169.5" x2="270" y2="78.1" style="stroke:var(--accent)" stroke-width="2.2"/><line x1="195" y1="78.1" x2="270" y2="78.1" style="stroke:var(--accent)" stroke-width="2.2"/><line x1="95" y1="200" x2="95" y2="47.6" style="stroke:var(--accent)" stroke-width="2.2"/><line x1="145" y1="200" x2="145" y2="47.6" style="stroke:var(--accent)" stroke-width="2.2"/><line x1="95" y1="47.6" x2="145" y2="47.6" style="stroke:var(--accent)" stroke-width="2.2"/><line x1="120" y1="47.6" x2="120" y2="25.9" style="stroke:var(--accent)" stroke-width="2.2"/><line x1="232.5" y1="78.1" x2="232.5" y2="25.9" style="stroke:var(--accent)" stroke-width="2.2"/><line x1="120" y1="25.9" x2="232.5" y2="25.9" style="stroke:var(--accent)" stroke-width="2.2"/><text x="95" y="218" text-anchor="middle" font-size="12" fill="currentColor" font-weight="700">1</text><text x="145" y="218" text-anchor="middle" font-size="12" fill="currentColor" font-weight="700">2</text><text x="195" y="218" text-anchor="middle" font-size="12" fill="currentColor" font-weight="700">3</text><text x="245" y="218" text-anchor="middle" font-size="12" fill="currentColor" font-weight="700">4</text><text x="295" y="218" text-anchor="middle" font-size="12" fill="currentColor" font-weight="700">5</text><line x1="68" y1="62.9" x2="332" y2="62.9" style="stroke:var(--fail)" stroke-width="2" stroke-dasharray="7 4"/><circle cx="95" cy="62.9" r="4.5" style="fill:var(--fail)"/><circle cx="145" cy="62.9" r="4.5" style="fill:var(--fail)"/><circle cx="232.5" cy="62.9" r="4.5" style="fill:var(--fail)"/><text x="338" y="58.9" text-anchor="start" font-size="12" style="fill:var(--fail)" font-weight="700">cut → 3 clusters:</text><text x="338" y="76.9" text-anchor="start" font-size="12" style="fill:var(--fail)" font-weight="700">{1} {2} {3, 4, 5}</text></svg></div>
<p><b>Choosing the number of clusters:</b> cut the tree with a horizontal line. Each vertical branch it crosses is one cluster: everything hanging below it. High cut → few clusters, low cut → many.</p>
<p><b>Where to cut:</b> in a tall empty stretch. Below it the merges were cheap (close groups); the next merge costs a lot, so it would join groups that really are apart. Like the elbow: a heuristic.</p>`,
      remember: R`<p>Number of clusters = the number of vertical lines the cut crosses. Not on the sheet.</p>`,
      try: { src: "Course summary, p. 115 ('Choosing the Number of Clusters?')",
        q: R`<p>The page shows this same tree (4 & 5 merge at about 0.14, 3 joins them at 0.56, 1 & 2 at 0.7, all at 0.8) with 5 cuts: above 0.8, between 0.7 and 0.8, between 0.56 and 0.7, between 0.14 and 0.56, below 0.14. Which clusters does each cut give?</p>`,
        a: R`<div class="tw"><table><thead><tr><th>cut</th><th>crosses</th><th>clusters</th></tr></thead><tbody>
<tr><td>above 0.8</td><td>1</td><td>{1, 2, 3, 4, 5}</td></tr>
<tr><td>0.7 – 0.8</td><td>2</td><td>{1, 2} {3, 4, 5}</td></tr>
<tr><td>0.56 – 0.7</td><td>3</td><td>{1} {2} {3, 4, 5}</td></tr>
<tr><td>0.14 – 0.56</td><td>4</td><td>{1} {2} {3} {4, 5}</td></tr>
<tr><td>below 0.14</td><td>5</td><td>each sample alone</td></tr></tbody></table></div>` },
      mistakes: R`<ul><li>Count the vertical lines the cut crosses, not the bars above it.</li><li>The heights are merge distances, so they depend on the linkage.</li></ul>`,
      where: ["2026-A Q4.4"] },
  ];
})();
